	}

	/* @Override */
	public void setOptions(ToolOptions options) {
		this.options = options.copy();
	}

	/* @Override */
	public Options getDefaultOptions() {
		return new ToolOptions(CORRELATOR_NAME);
	}

	/* @Override */
	public int getPriority() {
		return EARLY_PRIORITY;
	}
